CREATE TABLE assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),course_id UUID NOT NULL REFERENCES training_courses(id),name VARCHAR(255) NOT NULL,assessment_date DATE,assessor VARCHAR(255),maximum_score NUMERIC(8,2) NOT NULL,pass_mark NUMERIC(5,2) NOT NULL);
CREATE TABLE scores(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,employee_id UUID NOT NULL REFERENCES employees(id),assessment_id UUID NOT NULL REFERENCES assessments(id),score NUMERIC(8,2) NOT NULL,maximum_score NUMERIC(8,2) NOT NULL,percentage NUMERIC(5,2) NOT NULL,pass_mark NUMERIC(5,2) NOT NULL,result VARCHAR(20) NOT NULL,assessor VARCHAR(255),score_date DATE NOT NULL,remarks TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(score>=0 AND score<=maximum_score));
CREATE TABLE certifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,employee_id UUID NOT NULL REFERENCES employees(id),course_id UUID REFERENCES training_courses(id),name VARCHAR(255) NOT NULL,issue_date DATE NOT NULL,expiry_date DATE,status VARCHAR(30) NOT NULL,document_key VARCHAR(500),renewal_required BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX idx_cert_expiry ON certifications(expiry_date,status);